*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDFIS00600_P3.xml";
window.onunload = function() {
    // 기업검색에서도 쓰기 때문에 try catch 로 묶는다
    try {
        opener.fn_getBeforeRadioBtn("ALL");
    } catch (E) {

    }
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};



/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    if (opener.scwin.vScrenID == "ULDFIS00600.gfm") {
        txb_IND_PTTN.setValue($c.stf.getObjectValue(opener.cmb_IND_PTTN));
        txb_ACNTG_BAS_TYP.setValue($c.stf.getObjectValue(opener.cmb_ACNTG_BAS_TYP));
        txb_INDVDL_CONN_TP.setValue($c.stf.getObjectValue(opener.cmb_INDVDL_CONN_TP));
    } else if (opener.scwin.vScrenID == "ULDFIS00600_P2.gfm" || opener.scwin.vScrenID == "ULDFIS00600_P5.gfm") {
        txb_IND_PTTN.setValue($c.stf.getObjectValue(opener.txb_IND_PTTN));
        txb_ACNTG_BAS_TYP.setValue($c.stf.getObjectValue(opener.txb_ACNTG_BAS_TYP));
        txb_INDVDL_CONN_TP.setValue($c.stf.getObjectValue(opener.txb_INDVDL_CONN_TP));
    }

    // 계정유형 조회
    scwin.fn_GetDtsAccntPttn();

    // 조회
    scwin.fn_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_Acnt.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    return true;
};


/**
 * 재무유형 조회
 */
scwin.fn_GetDtsAccntPttn = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.accntPttn" + "&outputMessageId=FIS_ACNTCLS_DT" + "&param01=" + $c.stf.getObjectValue(txb_ACNTG_BAS_TYP) + "&param02=" + $c.stf.getObjectValue(txb_IND_PTTN);
    dts_AccntPttn.DataID = encodeURI(url);
    dts_AccntPttn.Reset();
};


/**
 * 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(panel_Top);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.acnt" + "&outputMessageId=FIS_ACNT_LIST" + "&param01=" + $c.stf.getObjectValue(txb_ACNTG_BAS_TYP) + "&param02=" + $c.stf.getObjectValue(txb_IND_PTTN) + "&param03=" + $c.stf.getObjectValue(txb_INDVDL_CONN_TP) + "&param03=" + $c.stf.getObjectValue(txb_INDVDL_CONN_TP) + "&param04=" + $c.stf.getObjectValue(txb_ACCNT_NM) + "&param05=" + $c.stf.getObjectValue(cmb_ACCNT_PTTN);
    dts_Acnt.DataID = encodeURI(url);
    dts_Acnt.Reset();
};


/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.fn_SetParam = async function() {
    var nRow = dts_Acnt.getRowPosition();
    if (nRow < 1) {
        return;
    }
    var sItemCd = dts_Acnt.getCellData(nRow, "ACCNT_PTTN") + dts_Acnt.getCellData(nRow, "ACCNT_CD");
    var sItemNM = dts_Acnt.getCellData(nRow, "ACCNT_NM");
    var sItemTyp = "1"; // 0:년도, 1:계정, 3:회사
    var sAxisTyp = "1"; // AXIS_TYP  1:기준, 2: 가로, 3:세로
    var sColYear = "0000"; // COL_YEAR

    if (sItemCd != "") {
        var arrPar = new Array();
        arrPar[0] = {
            ITEM_CD: sItemCd,
            ITEM_NM: sItemNM,
            ITEM_TYP: sItemTyp,
            AXIS_TYP: sAxisTyp,
            COL_YEAR: sColYear
        };
        $c.frame.path("../").fn_SetAxisInfo(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.dts_Acnt_OnLoadError = function() {
    $c.stf.alert_error(dts_Acnt);
};
scwin.dts_Acnt_OnLoadCompleted = function(rowcount) {
    if (dts_Acnt.errorMsg) {
        $c.win.alert(dts_Acnt.errorMsg);
    }
    $c.cm.CloseWin(rowcount, panel_Top);
    //trv_Year.ExpandLevel = 1;
    //trv_Year.index = 1;

};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.img_Close_onclick = async function() {
    // 닫기버튼 클릭
    // opener.fn_getBeforeRadioBtn("ALL");
    await $c.frame.CloseFrame();
};
scwin.img_Confirm_onclick = function() {
    // 확인버튼 클릭
    scwin.fn_SetParam();
};
scwin.trv_Year_OnDblClick = function() {
    scwin.fn_SetParam();
};
scwin.txb_ACCNT_NM_onkeydown = function() {
    // 기업집단검색 팝업 오픈
    if (event.keyCode == 13) {
        scwin.fn_Search();
    }
};
scwin.btn_Search_onclick = function() {
    // 조회 버튼 클릭
    scwin.fn_Search();
};
scwin.cmb_ACCNT_PTTN_OnSelChange = function() {
    scwin.fn_Search();
};
